SELECT order_status, COUNT(*) AS num_orders 
FROM olist.orders 
GROUP BY order_status;

SELECT COUNT(*) 
FROM olist.orders 
WHERE order_status = 'delivered' AND (order_delivered_carrier_date IS NULL OR order_delivered_customer_date IS NULL);

SELECT COUNT(*) 
FROM olist.orders 
WHERE order_delivered_customer_date > order_estimated_delivery_date AND order_delivered_customer_date IS NOT NULL;
